// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(this));
        vm.assume(!(address(c) == caller || address(this) == caller));
        uint256 beforeLimit = c.currentBetLimit();
        vm.prank(caller);
        bool ok = true;
        try c.AdjustBetAmounts(amount) { } catch { ok = false; }
        uint256 afterLimit = c.currentBetLimit();
        assertTrue(ok ? afterLimit == beforeLimit : true);
    }
}
